    description: { de: "Balıkesir ist das Zentrum einer landwirtschaftlich geprägten Provinz, die sowohl an die Ägäis als auch an das Marmarameer grenzt.", hu: "Balıkesir egy mezőgazdasági jellegű tartomány központja, amely az Égei-tengerrel és a Márvány-tengerrel is határos.", ro: "Balıkesir este centrul unei provincii agricole care se învecinează atât cu Marea Egee, cât și cu Marea Marmara.", en: "Balıkesir is the center of an agricultural province that borders both the Aegean and the Sea of Marmara." , es: "Balıkesir es el centro de una provincia agrícola que limita tanto con el mar Egeo como con el mar de Mármara.", pt: "Balıkesir é o centro de uma província agrícola que faz fronteira tanto com o Mar Egeu quanto com o Mar de Mármara.", fr: "Balıkesir est le centre d'une province agricole bordée à la fois par la mer Égée et la mer de Marmara."},
